#!/usr/bin/env node
// floorplan/serve.mjs: serve this map locally and answer questions about the codebase through the
// Claude Code, Codex or Antigravity CLI. Generated by build.mjs; needs Node 18+.
//
// usage: node floorplan/serve.mjs [--provider auto|claude|codex|antigravity] [--model <model>] [--no-open]
//        node floorplan/serve.mjs --stop
//
// The server listens on 127.0.0.1 only. Questions run through the selected local CLI.
// Codex runs with a read-only sandbox; other providers receive restricted instructions.
// When the map is rebuilt, open tabs reload in place. The running server is recorded in .cache/server.json.
import http from 'node:http';
import fs from 'node:fs';
import path from 'node:path';
import crypto from 'node:crypto';
import { spawn, execFileSync } from 'node:child_process';
import { fileURLToPath } from 'node:url';
import { resolveProvider, providerEnv, providerRequest, handleProviderEvent } from './providers.mjs';

const here = path.dirname(fileURLToPath(import.meta.url));
const root = path.resolve(here, '..');
const argv = process.argv.slice(2);
const opt = (name, dflt) => { const i = argv.indexOf('--' + name); return i < 0 ? dflt : argv[i + 1]; };
const has = (name) => argv.includes('--' + name);
const stateFile = path.join(here, '.cache', 'server.json');
const readState = () => { try { return JSON.parse(fs.readFileSync(stateFile, 'utf8')); } catch { return null; } };
if (has('stop')) {
  const s = readState();
  let stopped = false;
  if (s?.pid) { try { process.kill(s.pid); stopped = true; } catch {} }
  try { fs.unlinkSync(stateFile); } catch {}
  console.log(stopped ? `Stopped the map server (${s.url}).` : 'The map server was not running.');
  process.exit(0);
}
const wantPort = Number(opt('port', 4378));
const idleExit = Number(opt('idle-exit', 0)) * 60000; // stop this long after the last tab closes (0 = never)
const selfHash = crypto.createHash('sha1').update(fs.readFileSync(fileURLToPath(import.meta.url))).digest('hex').slice(0, 12);
const model = opt('model', process.env.FLOORPLAN_MODEL || '');
const token = crypto.randomBytes(16).toString('hex');
const TYPES = { '.html': 'text/html; charset=utf-8', '.json': 'application/json', '.js': 'text/javascript', '.mjs': 'text/javascript', '.css': 'text/css', '.svg': 'image/svg+xml' };

// ---------- select the installed coding agent ----------
const provider = resolveProvider(opt('provider', process.env.FLOORPLAN_PROVIDER || 'auto'), {
  claude: opt('claude', process.env.FLOORPLAN_CLAUDE),
  codex: opt('codex', process.env.FLOORPLAN_CODEX),
  antigravity: opt('antigravity', process.env.FLOORPLAN_ANTIGRAVITY),
});
const claude = provider?.id === 'claude' ? provider : null;
const claudeEnv = () => providerEnv(provider);
let version = null;
if (provider) {
  try {
    version = execFileSync(provider.cmd, [...provider.prefix, '--version'], {
      encoding: 'utf8', timeout: 15000, stdio: ['ignore', 'pipe', 'ignore'],
      windowsHide: true, shell: provider.shell,
    }).trim();
  } catch {}
}

// The page, the graph, and the instructions and answer schema (from query.mjs's inlined graph-query
// code). Loaded at start and again whenever the map is rebuilt.
const inject = `<script>window.FLOORPLAN_SERVER=${JSON.stringify({ token, cli: !!provider, version, model: model || null, provider: provider?.id || null, providerLabel: provider?.label || null })};</script>`;
let page, G, core, MODES;
function load() {
  const html = fs.readFileSync(path.join(here, 'index.html'), 'utf8');
  const g = JSON.parse(fs.readFileSync(path.join(here, 'graph.json'), 'utf8'));
  const coreSrc = fs.readFileSync(path.join(here, 'query.mjs'), 'utf8').split('// ---- cli ----')[0];
  const c = new Function(`${coreSrc.replace(/^import .*$/gm, '')}; return { FLOORPLAN_ANSWER_SCHEMA, FLOORPLAN_FLOW_SCHEMA, floorplanAskInstructions, floorplanFlowInstructions, createGraphQuery };`)();
  c.q = c.createGraphQuery(g);
  page = html.replace('</head>', inject + '</head>');
  G = g; core = c;
  // two kinds of request: a question (answer + board) or a new guided flow
  MODES = {
    ask: { instructions: core.floorplanAskInstructions(G, 'cli'), schema: JSON.stringify(core.FLOORPLAN_ANSWER_SCHEMA) },
    flow: { instructions: core.floorplanFlowInstructions(G, 'cli'), schema: JSON.stringify(core.FLOORPLAN_FLOW_SCHEMA) },
  };
  const cache = path.join(here, '.cache');
  fs.mkdirSync(cache, { recursive: true });
  for (const [name, mode] of Object.entries(MODES)) {
    mode.schemaFile = path.join(cache, name + '-schema.json');
    fs.writeFileSync(mode.schemaFile, mode.schema);
  }
}
load();

// ---------- open tabs: live reload, and idle shutdown ----------
const tabs = new Set();
let lastTab = Date.now();
const broadcast = (event, data = {}) => { for (const t of tabs) t.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`); };
let reloadTimer = null;
fs.watchFile(path.join(here, 'index.html'), { interval: 1000 }, (cur, prev) => {
  if (cur.mtimeMs === prev.mtimeMs) return;
  // build writes several files; wait for it to finish, and keep serving the old map if the new one is half-written
  clearTimeout(reloadTimer);
  reloadTimer = setTimeout(() => { try { load(); broadcast('reload'); console.log('map rebuilt: reloaded open tabs'); } catch {} }, 800);
});
if (idleExit) setInterval(() => { if (!tabs.size && !running.size && Date.now() - lastTab > idleExit) process.exit(0); }, 60000).unref();
const flowsFile = path.join(here, 'custom-flows.json');
const readFlows = () => { try { return JSON.parse(fs.readFileSync(flowsFile, 'utf8')).flows || []; } catch { return []; } };

// ---------- Floorplan Cloud waitlist (opt-in) ----------
// The map may ask, once, whether you want an email when Floorplan Cloud launches. Nothing is sent unless
// you click "Notify me", and then only the email you see in the box and whether it's for you or a team.
// Where it goes: a small Cloud Run service that adds it to a Google Sheet (docs/privacy-and-security.md
// links its code). Your answer (joined, later,
// never) is kept in ~/.floorplan/settings.json so every project's map remembers it.
// FLOORPLAN_NO_PROMPTS=1 turns the question off.
const WAITLIST_URL = process.env.FLOORPLAN_WAITLIST_URL || 'https://floorplan-waitlist-690500262396.us-central1.run.app/';
const settingsFile = path.join(process.env.HOME || process.env.USERPROFILE || here, '.floorplan', 'settings.json');
const readSettings = () => { try { return JSON.parse(fs.readFileSync(settingsFile, 'utf8')); } catch { return {}; } };
function saveCloud(cloud) {
  try { fs.mkdirSync(path.dirname(settingsFile), { recursive: true }); fs.writeFileSync(settingsFile, JSON.stringify({ ...readSettings(), cloud }, null, 2) + '\n'); } catch {}
}
function cloudPrompt() {
  if (!WAITLIST_URL || /^(1|true|yes)$/i.test(process.env.FLOORPLAN_NO_PROMPTS || '')) return false;
  const c = readSettings().cloud || {};
  return !c.status || (c.status === 'later' && Date.now() > Date.parse(c.until || 0));
}
/** The email of the claude.ai account Claude Code is signed in with, or null (API key, Bedrock, not signed in). */
function claudeEmail() {
  if (!claude) return null;
  try {
    const out = execFileSync(claude.cmd, [...claude.args, 'auth', 'status', '--json'], { encoding: 'utf8', timeout: 15000, stdio: ['ignore', 'pipe', 'ignore'], windowsHide: true, env: claudeEnv() });
    const email = JSON.parse(out).email;
    return typeof email === 'string' && EMAIL.test(email) ? email : null;
  } catch { return null; }
}
// starts with a letter or digit, so a spreadsheet never reads it as a formula
const EMAIL = /^[A-Za-z0-9][^\s@]{0,63}@[^\s@]+\.[^\s@]{2,}$/;
async function joinWaitlist(body) {
  const email = String(body.email || '').trim();
  const use = body.use === 'team' ? 'team' : 'solo';
  if (!WAITLIST_URL) return { ok: false, error: 'not_configured' };
  if (email.length > 254 || !EMAIL.test(email)) return { ok: false, error: 'bad_email' };
  try {
    const r = await fetch(WAITLIST_URL, { method: 'POST', headers: { 'Content-Type': 'text/plain' }, body: JSON.stringify({ email, use }), redirect: 'follow', signal: AbortSignal.timeout(20000) });
    const out = await r.json().catch(() => ({}));
    if (!r.ok || !out.ok) return { ok: false, error: out.error || 'send_failed' };
  } catch { return { ok: false, error: 'send_failed' }; }
  saveCloud({ status: 'joined', at: new Date().toISOString() });
  return { ok: true };
}

// ---------- asking ----------
const nameFor = (id) => { try { return core.q.brief(id)?.name || id; } catch { return id; } };
const running = new Map();
function describeTool(name, input = {}) {
  const rel = (p) => String(p || '').replace(/\\/g, '/').replace(root.replace(/\\/g, '/') + '/', '');
  if (name === 'Bash') {
    // Claude often chains several lookups in one command; describe each one, by name
    const parts = String(input.command || '').split(/\s*(?:&&|;|\|\|)\s*/).map((c) => /query\.mjs\s+(\w+)\s*(.*)$/.exec(c)).filter(Boolean);
    if (!parts.length) return 'Running a command';
    const one = ([, cmd, rest]) => {
      const a = rest.replace(/--\w+\s+\S+/g, '').replace(/["']/g, '').trim();
      return { overview: 'Reading the map overview', find: `Searching the map for "${a}"`, show: `Looking at ${a.split(/\s+/).map(nameFor).join(', ')}`, path: `Tracing a path ${a.split(/\s+/).map(nameFor).join(' → ')}` }[cmd] || 'Querying the map';
    };
    return parts.slice(0, 2).map(one).join(' · ') + (parts.length > 2 ? ` (+${parts.length - 2} more)` : '');
  }
  if (name === 'Read') return `Reading ${rel(input.file_path)}`;
  if (name === 'Grep') return `Searching code for "${input.pattern}"`;
  if (name === 'Glob') return `Listing ${input.pattern}`;
  return name;
}
function parseAnswer(ev) {
  if (ev.structured_output && typeof ev.structured_output === 'object') return ev.structured_output;
  const t = String(ev.result || '');
  const fence = /```(?:json)?\s*([\s\S]*?)```/.exec(t);
  for (const cand of [t, fence?.[1], t.slice(t.indexOf('{'), t.lastIndexOf('}') + 1)]) { try { const v = JSON.parse(cand); if (v && typeof v === 'object') return v; } catch {} }
  return { title: 'Answer', answer: t, items: [] };
}
function ask(req, res, body) {
  res.writeHead(200, { 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-store', Connection: 'keep-alive' });
  const send = (event, data) => res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
  if (!provider) {
    send('failure', { code: 'cli_missing', message: 'No supported coding agent CLI found. Install Claude Code, Codex, or Antigravity, or select one with --provider.' });
    return res.end();
  }
  const mode = MODES[body.mode] || MODES.ask;
  const request = providerRequest(provider, {
    question: body.question, mode, session: body.session, model, schemaFile: mode.schemaFile,
  });
  const child = spawn(provider.cmd, request.args, {
    cwd: root, env: providerEnv(provider), stdio: ['pipe', 'pipe', 'pipe'],
    windowsHide: true, shell: provider.shell,
  });
  const id = crypto.randomBytes(6).toString('hex');
  running.set(id, child);
  send('start', { id });
  child.stdin.on('error', () => {}); // A failed early CLI launch can close stdin.
  child.stdin.end(request.input);
  let buf = '', stderr = '', done = false;
  const state = { last: '', session: null };
  child.stdout.on('data', (data) => {
    buf += data;
    let nl;
    while ((nl = buf.indexOf('\n')) >= 0) {
      const line = buf.slice(0, nl).trim();
      buf = buf.slice(nl + 1);
      if (!line) continue;
      let ev; try { ev = JSON.parse(line); } catch { continue; }
      const result = handleProviderEvent(provider, ev, state);
      if (!result) continue;
      if (result.progress) send('progress', { text: describeTool(result.progress.name, result.progress.input) });
      if (result.failure && !done) {
        done = true;
        const message = String(result.failure);
        send('failure', { code: /not logged in|login|authenticat|credential/i.test(message) ? 'not_logged_in' : 'cli_error', message });
      }
      if (result.answer && !done) {
        done = true;
        send('answer', { ...result.answer, session: result.session });
      }
    }
  });
  child.stderr.on('data', data => { stderr = (stderr + data).slice(-2000); });
  child.on('error', error => {
    if (!done) { done = true; send('failure', { code: 'cli_error', message: error.message }); }
    res.end();
  });
  child.on('close', code => {
    running.delete(id);
    if (!done) send('failure', {
      code: /not logged in|login|authenticat|credential/i.test(stderr) ? 'not_logged_in' : 'cli_error',
      message: stderr.trim() || provider.label + ' exited with code ' + code,
    });
    res.end();
  });
  res.on('close', () => { if (!done) child.kill(); });
}

// ---------- http ----------
const server = http.createServer((req, res) => {
  const url = new URL(req.url, `http://${req.headers.host}`);
  const sameOrigin = !req.headers.origin || req.headers.origin === `http://${req.headers.host}`;
  if (url.pathname.startsWith('/api/')) {
    // EventSource can't send headers, so the events stream takes the token in the query string
    const given = req.headers['x-floorplan-token'] || (url.pathname === '/api/events' ? url.searchParams.get('token') : null);
    if (!sameOrigin || given !== token) { res.writeHead(403); return res.end(); }
    if (req.method === 'GET' && url.pathname === '/api/events') {
      res.writeHead(200, { 'Content-Type': 'text/event-stream', 'Cache-Control': 'no-store', Connection: 'keep-alive' });
      res.write('retry: 1000\n\n'); // reconnect quickly after a restart
      tabs.add(res);
      req.on('close', () => { tabs.delete(res); lastTab = Date.now(); });
      return;
    }
    if (req.method === 'GET' && url.pathname === '/api/status') { res.writeHead(200, { 'Content-Type': 'application/json' }); return res.end(JSON.stringify({ tabs: tabs.size, pid: process.pid, hash: selfHash, root })); }
    if (req.method === 'GET' && url.pathname === '/api/health') { res.writeHead(200, { 'Content-Type': 'application/json' }); return res.end(JSON.stringify({ cli: !!provider, provider: provider?.id || null, providerLabel: provider?.label || null, version, path: provider?.path || null })); }
    // requested flows are saved next to the map; build.mjs folds them into graph.json
    if (url.pathname === '/api/flows') {
      if (req.method === 'GET') { res.writeHead(200, { 'Content-Type': 'application/json' }); return res.end(JSON.stringify({ flows: readFlows() })); }
      if (req.method === 'POST' || req.method === 'DELETE') {
        let raw = '';
        req.on('data', (d) => { raw += d; if (raw.length > 50000) req.destroy(); });
        req.on('end', () => {
          let body = {}; try { body = JSON.parse(raw); } catch {}
          let flows = readFlows().filter((x) => x.id !== body.id && x.id !== body.flow?.id);
          if (req.method === 'POST' && body.flow?.id && Array.isArray(body.flow.steps)) flows.push({ ...body.flow, createdAt: new Date().toISOString() });
          fs.writeFileSync(flowsFile, JSON.stringify({ flows }, null, 2) + '\n');
          res.writeHead(200, { 'Content-Type': 'application/json' }); res.end(JSON.stringify({ flows }));
        });
        return;
      }
    }
    if (url.pathname.startsWith('/api/cloud/')) {
      const json = (data) => { res.writeHead(200, { 'Content-Type': 'application/json' }); res.end(JSON.stringify(data)); };
      if (req.method === 'GET' && url.pathname === '/api/cloud/prompt') return json({ show: cloudPrompt() });
      if (req.method === 'POST') {
        let raw = '';
        req.on('data', (d) => { raw += d; if (raw.length > 2000) req.destroy(); });
        req.on('end', async () => {
          let body = {}; try { body = JSON.parse(raw); } catch {}
          // read only when the person clicks "Use my Claude email"
          if (url.pathname === '/api/cloud/claude-email') return json({ email: claudeEmail() });
          if (url.pathname === '/api/cloud/join') return json(await joinWaitlist(body));
          if (url.pathname === '/api/cloud/dismiss') {
            saveCloud(body.forever ? { status: 'never' } : { status: 'later', until: new Date(Date.now() + 14 * 864e5).toISOString() });
            return json({ ok: true });
          }
          res.writeHead(404); res.end();
        });
        return;
      }
    }
    if (req.method === 'POST' && url.pathname === '/api/cancel') { for (const c of running.values()) c.kill(); res.writeHead(204); return res.end(); }
    if (req.method === 'POST' && url.pathname === '/api/ask') {
      let raw = '';
      req.on('data', (d) => { raw += d; if (raw.length > 20000) req.destroy(); });
      req.on('end', () => { let body = {}; try { body = JSON.parse(raw); } catch {} ask(req, res, body); });
      return;
    }
    res.writeHead(404); return res.end();
  }
  if (url.pathname === '/' || url.pathname === '/index.html') { res.writeHead(200, { 'Content-Type': TYPES['.html'], 'Cache-Control': 'no-store' }); return res.end(page); }
  let file;
  try { file = path.join(here, decodeURIComponent(url.pathname)); } catch { res.writeHead(400); return res.end('bad address'); }
  // inside this folder only: a neighbour like ../floorplan-old/ also starts with this folder's path
  if (!file.startsWith(here + path.sep) || !fs.existsSync(file) || !fs.statSync(file).isFile()) { res.writeHead(404); return res.end('not found'); }
  res.writeHead(200, { 'Content-Type': TYPES[path.extname(file)] || 'application/octet-stream' });
  fs.createReadStream(file).pipe(res);
});
// another map (or anything else) on the port: take the next free one
let port = wantPort;
server.on('error', (e) => {
  if (e.code === 'EADDRINUSE' && port < wantPort + 20) { port++; server.listen(port, '127.0.0.1'); return; }
  console.error(`✗ Couldn't start the map server: ${e.message}`);
  process.exit(1);
});
server.listen(port, '127.0.0.1');
server.on('listening', () => {
  const u = `http://127.0.0.1:${port}`;
  try {
    fs.mkdirSync(path.dirname(stateFile), { recursive: true });
    fs.writeFileSync(stateFile, JSON.stringify({ pid: process.pid, port, url: u, token, hash: selfHash, startedAt: new Date().toISOString() }, null, 2));
  } catch {}
  const forget = () => { try { if (readState()?.pid === process.pid) fs.unlinkSync(stateFile); } catch {} };
  process.on('exit', forget);
  for (const sig of ['SIGINT', 'SIGTERM', 'SIGHUP']) process.on(sig, () => process.exit(0));
  console.log(`Floorplan: ${u}`);
  console.log(provider ? `asking via ${provider.label} CLI ${version || ''} (${provider.path})${model ? `, model ${model}` : ''}` : 'No supported coding agent CLI found. Pass --provider claude|codex|antigravity or install a CLI.');
  if (!has('no-open')) {
    const opener = process.platform === 'win32' ? ['cmd', ['/c', 'start', '', u]] : process.platform === 'darwin' ? ['open', [u]] : ['xdg-open', [u]];
    try { spawn(opener[0], opener[1], { stdio: 'ignore', detached: true }).unref(); } catch {}
  }
});
